{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Betaxolol, a structurally related aryloxypropanolamine beta-blocker, had absolute oral bioavailability of 83.9 ± 6.6% after a 40 mg oral dose versus IV, supporting high F for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Celiprolol, a urea-containing beta-blocker closely related to the query, showed oral bioavailability of 30% at 100 mg and up to 70% at higher doses, remaining above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Diacetolol, another para-substituted aryloxypropanolamine, had absolute F of 30.2 ± 5.2% at 100 mg, demonstrating that even lower-F analogues remain above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Practolol, a close structural analogue, had absolute oral bioavailability of 90–100%, indicating high absorption for this beta-blocker scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "CP-331,684, a related beta-blocker, had a bioavailability of 27% in humans, the lowest among the analogues yet still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Almokalant, another aryloxypropanolamine-like drug, had absolute F of approximately 50% in healthy volunteers, supporting high oral bioavailability for this class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All high-transfer analogues are beta-blockers with absolute oral bioavailability well above 20% (27–100%). The query is talinolol, whose baseline F is about 55%; rifampin co-treatment can lower exposure via intestinal P-gp induction, but the expected F remains at or near the 20% threshold, supporting a high prediction.",
  "evidence_gaps": [
    "No direct talinolol or rifampin co-treatment record is present in the supplied evidence; the rifampin effect is inferred from known P-gp induction and the high baseline F of the query class.",
    "The exact post-rifampin F for the query is not directly measured in the evidence set, so the margin above the 20% threshold is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

